insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('27bc32b3-3770-4e93-9ed9-1775d595ebcb', 'dece71ca-c31b-492f-b616-37742b7e09bc', $$uit een krant (december 2017): basispakket, eigen risico, aanvullende zorgverzekering en rationeler klantgedrag$$,
   $$economie-havo-2021-ii-eigen-risico-en-aanvullende-verzekering-context1.png$$,
   $$uit een krant, december 2017: Iedereen die in Nederland woont of werkt, moet een basisverzekering voor zorg - kortweg basispakket - afsluiten. De overheid bepaalt wat onder het basispakket valt en wat niet. Daarnaast kunnen mensen een aanvullende zorgverzekering afsluiten om kosten te verzekeren die buiten het basispakket vallen, zoals tandzorg, fysiotherapie, hulpmiddelen of alternatieve geneeswijzen. Het basispakket heeft een verplicht eigen risico van minimaal € 385 per persoon per jaar. Verzekerden die kiezen voor een vrijwillig verhoogd eigen risico, krijgen korting op de premie. De gezamenlijke zorgverzekeringsmaatschappijen zien een trend dat verzekerden zich steeds rationeler gedragen:
− Klanten verzekeren zich alleen nog voor aanvullende zorg waarvan zij (bijna) zeker weten dat zij die gaan gebruiken.
− Gezonde mensen kiezen steeds vaker voor een verhoogd eigen risico bij het basispakket.$$, 'inline'),
  ('3ffd1a61-e6f8-45ca-aa9d-cfd531dbc5a9', 'dece71ca-c31b-492f-b616-37742b7e09bc', $$het veranderende klantgedrag kan duiden op een verandering in risico-aversie (zie bron 2 en bron 3)$$,
   $$economie-havo-2021-ii-eigen-risico-en-aanvullende-verzekering-context2.png$$,
   $$Het veranderende klantgedrag kan duiden op een verandering in risico- aversie bij verzekerden (zie bron 2 en bron 3).$$, 'inline'),
  ('5c8932f1-6acb-45b3-a2e9-cc1bbc3b946e', 'dece71ca-c31b-492f-b616-37742b7e09bc', $$DSW geeft € 276 premiekorting bij een vrijwillig eigen risico van € 885; 13% kiest daarvoor$$,
   $$economie-havo-2021-ii-eigen-risico-en-aanvullende-verzekering-context3.png$$,
   $$Zorgverzekeraar DSW introduceert voor het jaar 2018 een premiekorting van € 276 per persoon per jaar voor verzekerden die het eigen risico bij het basispakket met € 500 verhogen van € 385 naar € 885. Voorheen hadden alle verzekerden bij DSW alleen het verplichte eigen risico van € 385 per persoon per jaar. Stel dat 13% van de verzekerden van DSW vrijwillig kiest voor een verhoging van het eigen risico naar € 885. Ga ervan uit dat het aantal verzekerden bij DSW in 2017 en 2018 gelijk is (zie bron 1).$$, 'inline'),
  ('2df46824-3b87-45b4-a218-f3420ca2ed18', 'dece71ca-c31b-492f-b616-37742b7e09bc', $$bron 1: marktaandelen zorgverzekeringsmaatschappijen (2017)$$,
   $$economie-havo-2021-ii-eigen-risico-en-aanvullende-verzekering-context4.png$$,
   $$bron 1 marktaandelen1) zorgverzekeringsmaatschappijen als percentage van de 17 miljoen verzekerden (2017)
cirkeldiagram: Achmea 30,4% | VGZ 23,8% | CZ 21,1% | Menzis 13,0% | DSW 3,5% | ONVZ 2,7% | Zorg en Zekerheid 2,6% | ASR 2,1% | Eno 0,8%
noot 1 op de markt voor basisverzekeringen voor zorg$$, 'inline'),
